```cpp
#include <hexi/hexi.h>
#include <cstdint>
#include <span>

struct MessageHeader {
    uint16_t message_type;
    uint32_t body_length;
    uint32_t footer;
};

MessageHeader read_header_and_skip_body(const std::span<const uint8_t> buffer) {
    // Create a binary stream reader from the buffer
    hexi::binary_stream_reader reader(buffer);

    // Read the message_type (uint16_t)
    uint16_t message_type = reader.read_u16();

    // Read the body_length (uint32_t)
    uint32_t body_length = reader.read_u32();

    // Skip the body_data of length body_length
    reader.skip(body_length);

    // Read the footer (uint32_t)
    uint32_t footer = reader.read_u32();

    // Return the MessageHeader structure
    return MessageHeader{message_type, body_length, footer};
}
```

