#include <hexi/hexi.h>
#include <vector>
#include <cstdint>

std::vector<uint8_t> read_buffer_data(const std::vector<uint8_t>& source_buffer, size_t bytes_to_read) {
    // Create a non-const copy since buffer adaptor requires non-const reference
    std::vector<uint8_t> buffer_copy = source_buffer;

    // Create buffer read adaptor
    hexi::pmc::buffer_read_adaptor adaptor(buffer_copy);

    // Ensure we don't read more than available
    size_t actual_bytes_to_read = std::min(bytes_to_read, source_buffer.size());

    // Create destination buffer
    std::vector<uint8_t> destination(actual_bytes_to_read);

    // Read the specified number of bytes
    adaptor.read(destination.data(), actual_bytes_to_read);

    return destination;
}

void write_buffer_data(std::vector<uint8_t>& dest_buffer, const std::vector<uint8_t>& source_data) {
    // Resize destination buffer if needed to accommodate the source data
    if (dest_buffer.size() < source_data.size()) {
        dest_buffer.resize(source_data.size());
    }

    // Create buffer adaptor for the destination
    hexi::pmc::buffer_adaptor adaptor(dest_buffer);

    // Write the source data to the destination buffer
    adaptor.write(source_data.data(), source_data.size());
}
```

The second implementation is more robust as it:
1. Handles the case where we try to read more bytes than available in the source buffer
2. Properly resizes the destination buffer when writing to ensure it can hold the source data
