struct DataResult {
    uint8_t data_type;
    std::vector<uint32_t> int_items;
    std::vector<float> float_items;
};

DataResult preview_and_read_data(const std::span<const uint8_t> buffer) {
    DataResult result;

    // Create a buffer adaptor for the input buffer
    hexi::buffer_adaptor adaptor(buffer);

    // Preview the first byte (data_type) without advancing the read pointer
    if (adaptor.size() < 1) {
        throw std::runtime_error("Buffer too small to read data_type");
    }

    // Peek at the data_type without consuming it
    result.data_type = static_cast<uint8_t>(adaptor[0]);

    // Check available data size - we need at least 5 bytes (1 for data_type + 4 for item_count)
    if (adaptor.size() < 5) {
        throw std::runtime_error("Buffer too small to read header");
    }

    // Create a binary stream for reading
    hexi::binary_stream stream(adaptor);

    // Read data_type (this will advance the pointer)
    stream >> result.data_type;

    // Read item_count
    uint32_t item_count;
    stream >> item_count;

    // Calculate required size: header (5 bytes) + items
    size_t required_size = 5;
    if (result.data_type == 0) { // integers
        required_size += item_count * sizeof(uint32_t);
    } else if (result.data_type == 1) { // floats
        required_size += item_count * sizeof(float);
    } else {
        throw std::runtime_error("Invalid data_type");
    }

    if (adaptor.size() < required_size) {
        throw std::runtime_error("Buffer too small for the specified item_count");
    }

    // Read items based on data_type
    if (result.data_type == 0) { // integers
        result.int_items.resize(item_count);
        for (uint32_t i = 0; i < item_count; ++i) {
            stream >> result.int_items[i];
        }
    } else if (result.data_type == 1) { // floats
        result.float_items.resize(item_count);
        for (uint32_t i = 0; i < item_count; ++i) {
            stream >> result.float_items[i];
        }
    }

    return result;
}
