#include <hexi/hexi.h>
#include <vector>
#include <cstdint>

bool write_data_with_check(std::vector<uint8_t>& buffer, uint32_t header, const std::vector<uint32_t>& items) {
    // Create buffer adaptor
    auto adaptor = hexi::make_buffer_adaptor(buffer);

    // Calculate required space: header (4 bytes) + vector size (4 bytes) + items (each 4 bytes)
    size_t required_space = sizeof(uint32_t) + sizeof(uint32_t) + (items.size() * sizeof(uint32_t));

    // Check available space
    if (adaptor.write_available() < required_space) {
        return false; // Insufficient space
    }

    // Create binary stream for writing
    auto stream = hexi::make_binary_stream(adaptor);

    // Write header
    stream.write(header);

    // Write container data
    stream.write_container(items);

    return true; // Write successful
}
```

