struct PacketHeader {
    uint32_t magic;
    uint16_t version;
    uint16_t flags;
};

PacketHeader read_header_with_span(const std::span<const uint8_t> buffer) {
    // Create a buffer_adaptor from the input span
    hexi::buffer_adaptor adaptor(buffer);

    // Check if there's enough data available for the header
    constexpr size_t header_size = sizeof(PacketHeader);
    if (adaptor.size() < header_size) {
        throw std::runtime_error("Insufficient data for packet header");
    }

    // Get the read pointer using buffer_adaptor method
    const uint8_t* read_ptr = adaptor.read_ptr();

    // Check available data
    size_t available = adaptor.size();

    // Create a binary_stream for zero-copy operations
    hexi::binary_stream stream(adaptor);

    // Get a zero-copy view of the header using binary_stream's span method
    auto header_span = stream.span<PacketHeader>(1);

    // The span gives us direct access to the header data without copying
    // We can simply return the first (and only) element from the span
    return header_span[0];
}
