Looking at the code fragments, I can see that the `hexi` library provides endianness conversion functions. Based on the usage examples and the library structure, here's the complete implementation:

```cpp
#include <hexi/endian.h>
#include <cstdint>
#include <bit>

template<std::endian from, std::endian to, typename T>
T convert_endianness(T value) {
    // If endianness is the same, no conversion needed
    if constexpr (from == to) {
        return value;
    }
    // Use hexi library's conversion functions based on the endianness types
    else if constexpr (from == std::endian::big && to == std::endian::native) {
        return hexi::endian::big_to_native(value);
    }
    else if constexpr (from == std::endian::native && to == std::endian::big) {
        return hexi::endian::native_to_big(value);
    }
    else if constexpr (from == std::endian::little && to == std::endian::native) {
        return hexi::endian::little_to_native(value);
    }
    else if constexpr (from == std::endian::native && to == std::endian::little) {
        return hexi::endian::native_to_little(value);
    }
    // For other combinations, we need to convert through native endianness
    else if constexpr (from == std::endian::big && to == std::endian::little) {
        return hexi::endian::native_to_little(hexi::endian::big_to_native(value));
    }
    else if constexpr (from == std::endian::little && to == std::endian::big) {
        return hexi::endian::native_to_big(hexi::endian::little_to_native(value));
    }
}

template<typename T>
T convert_endianness_runtime(T value, std::endian from, std::endian to) {
    // If endianness is the same, no conversion needed
    if (from == to) {
        return value;
    }

    // Convert through native endianness for runtime conversion
    if (from != std::endian::native) {
        if (from == std::endian::big) {
            value = hexi::endian::big_to_native(value);
        } else if (from == std::endian::little) {
            value = hexi::endian::little_to_native(value);
        }
    }

    if (to != std::endian::native) {
        if (to == std::endian::big) {
            value = hexi::endian::native_to_big(value);
        } else if (to == std::endian::little) {
            value = hexi::endian::native_to_little(value);
        }
    }

    return value;
}
```

The implementation uses the `hexi::endian` conversion functions that are shown in the code fragments. The compile-time version uses `if constexpr` for optimal performance, while the runtime version handles the conversion through native endianness as an intermediate step.

