Looking at the code fragments and the Hexi library structure, I can see that `hexi::file_buffer` is the main class for file operations. Here's the complete implementation of the requested functions:

```cpp
#include <hexi/file_buffer.h>
#include <vector>
#include <cstdint>
#include <filesystem>

std::vector<uint8_t> read_file_data(const std::filesystem::path& file_path, size_t bytes_to_read) {
    hexi::file_buffer buffer(file_path);
    if (!buffer) {
        return {}; // Return empty vector if file open failed
    }

    std::vector<uint8_t> data(bytes_to_read);
    buffer.read(data.data(), bytes_to_read);

    return data;
}

std::vector<uint8_t> preview_file_data(const std::filesystem::path& file_path, size_t bytes_to_preview) {
    hexi::file_buffer buffer(file_path);
    if (!buffer) {
        return {}; // Return empty vector if file open failed
    }

    // Get current read position
    size_t current_pos = buffer.tell();

    // Read the data
    std::vector<uint8_t> data(bytes_to_preview);
    buffer.read(data.data(), bytes_to_preview);

    // Restore original position
    buffer.seek(current_pos);

    return data;
