```cpp
#include <hexi/pmc/binary_stream_writer.h>
#include <hexi/pmc/binary_stream_reader.h>
#include <hexi/pmc/buffer_adaptor.h>
#include <vector>
#include <cstdint>

struct UserData {
    uint32_t user_id;
    std::string name;

    void serialise(auto& stream) {
        stream << user_id << name;
    }
};

void serialize_object(hexi::pmc::binary_stream_writer& writer, const UserData& data) {
    // Create a non-const copy since the serialise method might need non-const reference
    UserData temp = data;
    writer.deserialise(temp);
}

void deserialize_object(hexi::pmc::binary_stream_reader& reader, UserData& data) {
    reader.deserialise(data);
}
```

Alternatively, you can also use the stream operator approach which is more idiomatic:

```cpp
#include <hexi/pmc/binary_stream_writer.h>
#include <hexi/pmc/binary_stream_reader.h>
#include <hexi/pmc/buffer_adaptor.h>
#include <vector>
#include <cstdint>

struct UserData {
    uint32_t user_id;
    std::string name;

    void serialise(auto& stream) {
        stream << user_id << name;
    }
};

void serialize_object(hexi::pmc::binary_stream_writer& writer, const UserData& data) {
    // Create a non-const copy since the operator>> might need non-const reference
    UserData temp = data;
    writer >> temp;
}

void deserialize_object(hexi::pmc::binary_stream_reader& reader, UserData& data) {
    reader >> data;
}
```

