#include "implementation.hpp"

TEST(BufferAdaptors, WriteAndReadData) {
    std::vector<uint8_t> input = {1, 2, 3, 4, 5, 6, 7, 8};

    auto result = write_and_read_data(input);

    EXPECT_EQ(input.size(), result.size());
    EXPECT_EQ(input, result);
}

TEST(BufferAdaptors, WriteAndReadLargeData) {
    std::vector<uint8_t> input(1000);
    for (std::size_t i = 0; i < input.size(); ++i) {
        input[i] = static_cast<uint8_t>(i % 256);
    }

    auto result = write_and_read_data(input);

    EXPECT_EQ(input.size(), result.size());
    EXPECT_EQ(input, result);
}

TEST(BufferAdaptors, PeekWithoutAdvancing) {
    std::vector<uint8_t> buffer_data = {10, 20, 30, 40, 50};

    auto peeked = peek_data_without_advancing(buffer_data, 3);

    EXPECT_EQ(3, peeked.size());
    EXPECT_EQ(10, peeked[0]);
    EXPECT_EQ(20, peeked[1]);
    EXPECT_EQ(30, peeked[2]);
}

TEST(BufferAdaptors, PeekThenRead) {
    std::vector<uint8_t> buffer_data = {100, 200, 44, 144};
    std::vector<uint8_t> buffer = buffer_data;

    hexi::pmc::buffer_read_adaptor read_adaptor(buffer);

    // Peek first 2 bytes
    std::vector<uint8_t> peeked(2);
    read_adaptor.copy(peeked.data(), 2);

    // Verify peeked data
    EXPECT_EQ(100, peeked[0]);
    EXPECT_EQ(200, peeked[1]);

    // Verify read pointer hasn't advanced (size should still be full)
    EXPECT_EQ(buffer_data.size(), read_adaptor.size());

    // Now read to consume
    std::vector<uint8_t> read_data(2);
    read_adaptor.read(read_data.data(), 2);

    // Verify read data matches peeked data
    EXPECT_EQ(peeked, read_data);

    // Verify size decreased
    EXPECT_EQ(buffer_data.size() - 2, read_adaptor.size());
}

TEST(BufferAdaptors, ReadPtrAccess) {
    std::vector<uint8_t> buffer_data = {5, 10, 15, 20};
    std::vector<uint8_t> buffer = buffer_data;

    hexi::pmc::buffer_read_adaptor read_adaptor(buffer);

    // Get read pointer
    auto* read_pos = read_adaptor.read_ptr();

    // Verify pointer points to correct data
    EXPECT_EQ(5, static_cast<uint8_t>(*read_pos));

    // Read one byte
    uint8_t value;
    read_adaptor.read(&value);

    EXPECT_EQ(5, value);

    // Get new read pointer
    auto* new_read_pos = read_adaptor.read_ptr();
    EXPECT_EQ(10, static_cast<uint8_t>(*new_read_pos));
}

TEST(BufferAdaptors, FreeSpaceCheck) {
    std::vector<uint8_t> buffer(100, 0);
    hexi::pmc::buffer_adaptor adaptor(buffer);

    // Check initial free space (calculate from buffer size and write offset)
    std::size_t initial_free = adaptor.buffer_write_adaptor<std::vector<uint8_t>>::free();
    EXPECT_EQ(0, initial_free); // buffer is full (100 bytes), write_offset is at 100

    // Write some data
    std::vector<uint8_t> data = {1, 2, 3, 4, 5};
    adaptor.write(data.data(), data.size());

    // Check free space after write
    std::size_t free_after = adaptor.buffer_write_adaptor<std::vector<uint8_t>>::free();
    EXPECT_EQ(0, free_after); // For std::vector that auto-grows, free() is always 0 after write
}

