#include <cstdint>

std::size_t write_multiple_chunks(const std::vector<std::vector<uint8_t>>& chunks) {
    // Create a buffer large enough to hold all chunks
    std::size_t total_size = 0;
    for (const auto& chunk : chunks) {
        total_size += chunk.size();
    }

    std::vector<uint8_t> buffer(total_size);
    hexi::pmc::buffer_write_adaptor<std::vector<uint8_t>> writer(buffer);

    // Write each chunk separately
    for (const auto& chunk : chunks) {
        // Check available space before each write
        if (writer.free() < chunk.size()) {
            // Not enough space, resize buffer
            buffer.resize(buffer.size() + chunk.size() - writer.free());
            writer = hexi::pmc::buffer_write_adaptor<std::vector<uint8_t>>(buffer);
        }

        // Write the chunk data
        for (auto byte : chunk) {
            writer.write(byte);
        }
    }

    return writer.size();
}

std::vector<uint8_t> read_partial_data(const std::vector<uint8_t>& buffer, std::size_t chunk_size) {
    hexi::pmc::buffer_read_adaptor<const std::vector<uint8_t>> reader(buffer);
    std::vector<uint8_t> result;

    // Read data in chunks until buffer is empty
    while (reader.size() > 0) {
        // Read only a portion of available data
        std::size_t read_size = std::min(chunk_size, reader.size());

        for (std::size_t i = 0; i < read_size; ++i) {
            result.push_back(reader.read());
        }

        // Check remaining data after each read
        // The loop condition will check if we should continue
    }

    return result;
}

