```cpp
#include <hexi/hexi.h>
#include <hexi/endian.h>
#include <vector>
#include <cstdint>
#include <string>

struct MeasurementData {
    uint32_t sensor_id;
    std::vector<float> temperatures;
    double pressure;

    void serialise(auto& adaptor) const {
        // Write sensor_id directly (no endian conversion needed for serialization)
        adaptor << sensor_id;

        // Write the size of temperatures vector first
        uint32_t size = static_cast<uint32_t>(temperatures.size());
        adaptor << size;

        // Convert each temperature from native to little-endian and write
        for (const auto& temp : temperatures) {
            // Convert from native to little-endian for serialization
            float converted_temp = hexi::endian::conditional_reverse(temp, std::endian::native, std::endian::little);
            adaptor << converted_temp;
        }

        // Convert pressure from native to little-endian and write
        double converted_pressure = hexi::endian::conditional_reverse(pressure, std::endian::native, std::endian::little);
        adaptor << converted_pressure;
    }

    void serialise(auto& adaptor) {
        // Read sensor_id directly
        adaptor >> sensor_id;

        // Read the size of temperatures vector
        uint32_t size = 0;
        adaptor >> size;

        // Resize the vector and read each temperature
        temperatures.resize(size);
        for (auto& temp : temperatures) {
            adaptor >> temp;
            // Convert from little-endian to native in-place
            hexi::endian::little_to_native_inplace(temp);
        }

        // Read pressure and convert from little-endian to native
        adaptor >> pressure;
        hexi::endian::little_to_native_inplace(pressure);
    }
};

std::vector<uint8_t> serialize_measurement_data(const MeasurementData& data) {
    std::vector<uint8_t> buffer;
    hexi::pmc::buffer_adaptor adaptor(buffer);

