    MeasurementData data;
    hexi::pmc::buffer_adaptor adaptor(buffer);

    // Use the serialise method of MeasurementData (deserialization overload)
    adaptor.serialise(data);

    return data;
}

struct SensorInfo {
    uint32_t sensor_id;
    std::string_view sensor_name;
};

SensorInfo extract_sensor_info(const std::span<const uint8_t> buffer) {
    SensorInfo info;
    hexi::pmc::buffer_adaptor adaptor(buffer);

    // Use enforce_read_bounds to check if there's enough data for sensor_id
    adaptor.enforce_read_bounds(sizeof(uint32_t));

    // Read sensor_id directly
    adaptor >> info.sensor_id;

    // Try to extract a null-terminated sensor name string using view
    // Note: This assumes the sensor name comes after sensor_id in the buffer
    // If the structure doesn't actually contain a sensor name, this will need adjustment
    info.sensor_name = adaptor.view('\0');

    // Skip the remaining data
    adaptor.skip(adaptor.remaining());

    return info;
}
